package org.mockito.internal.util.reflection;

import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.exceptions.base.MockitoException;
import org.mockito.internal.util.Checks;
import org.mockito.internal.util.reflection.GenericMetadataSupport;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class GenericMetadataSupport_registerTypeVariablesOn_TriageGen1Test {

    private GenericMetadataSupport sut;

    // Since the method is protected, we create a test subclass to expose it
    private static class TestableGenericMetadataSupport extends GenericMetadataSupport {
        @Override
        public Class<?> rawType() {
            return null;
        }

        @Override
        public java.util.List<Type> extraInterfaces() {
            return null;
        }

        @Override
        public Class<?>[] rawExtraInterfaces() {
            return null;
        }

        @Override
        public boolean hasRawExtraInterfaces() {
            return false;
        }

        @Override
        public Map<TypeVariable, Type> actualTypeArguments() {
            return null;
        }

        @Override
        public Type getActualTypeArgumentFor(TypeVariable typeParameter) {
            return null;
        }

        @Override
        public GenericMetadataSupport resolveGenericReturnType(java.lang.reflect.Method method) {
            return null;
        }

        // Expose the protected method for testing
        public void callRegisterTypeVariablesOn(Type type) {
            super.registerTypeVariablesOn(type);
        }

        // Accessor for the internal map to verify results
        // Note: contextualActualTypeParameters is protected in the original class
        public Map<TypeVariable, Type> getContextualActualTypeParameters() {
            return this.contextualActualTypeParameters;
        }

        // Mocking the boundsOf method if it's not easily accessible or needs specific behavior
        // However, since we are testing the logic, we assume boundsOf is part of the inheritance
        // and returns something based on the WildcardType.
    }

    @Before
    public void setUp() {
        sut = new TestableGenericMetadataSupport();
    }

    /**
     * Test case where classType is not a ParameterizedType.
     * Covers the first 'if' branch (the return statement).
     */
    @Test
    public void testRegisterTypeVariablesOn_NotParameterizedType() {
        Type nonParameterizedType = String.class;
        sut.callRegisterTypeVariablesOn(nonParameterizedType);
        assertTrue(sut.getContextualActualTypeParameters().isEmpty());
    }

    /**
     * Test case where classType is a ParameterizedType with concrete types.
     * Covers the 'else' branch of the loop.
     */
    @Test
    public void testRegisterTypeVariablesOn_ParameterizedTypeWithConcreteArguments() throws Exception {
        // We use a real parameterized type: List<String>
        ParameterizedType parameterizedType = new FakeParameterizedType(List.class, new Type[]{String.class});

        sut.callRegisterTypeVariablesOn(parameterizedType);

        Map<TypeVariable, Type> result = sut.getContextualActualTypeParameters();
        assertEquals(1, result.size());

        TypeVariable<?> typeVar = List.class.getTypeParameters()[0];
        assertTrue(result.containsKey(typeVar));
        assertEquals(String.class, result.get(typeVar));
    }

    /**
     * Test case where classType is a ParameterizedType containing a WildcardType.
     * Covers the 'if (actualTypeArgument instanceof WildcardType)' branch.
     */
    @Test
    public void testRegisterTypeVariablesOn_ParameterizedTypeWithWildcard() throws Exception {
        // Simulating List<? extends Number>
        Type wildcardType = new FakeWildcardType(Number.class);
        ParameterizedType parameterizedType = new FakeParameterizedType(List.class, new Type[]{wildcardType});

        sut.callRegisterTypeVariablesOn(parameterizedType);

        Map<TypeVariable, Type> result = sut.getContextualActualTypeParameters();
        TypeVariable<?> typeVar = List.class.getTypeParameters()[0];

        // Since we cannot easily mock the protected 'boundsOf' without PowerMock, 
        // we rely on the fact that the code calls boundsOf. 
        // In a real environment, boundsOf(WildcardType) would return the bounds.
        // For this unit test, we verify that the map contains an entry for the type variable.
        assertTrue(result.containsKey(typeVar));
    }

    /**
     * Test case with multiple type arguments.
     */
    @Test
    public void testRegisterTypeVariablesOn_MultipleArguments() throws Exception {
        // Simulating Map<String, Integer>
        ParameterizedType parameterizedType = new FakeParameterizedType(Map.class, new Type[]{String.class, Integer.class});

        sut.callRegisterTypeVariablesOn(parameterizedType);

        Map<TypeVariable, Type> result = sut.getContextualActualTypeParameters();
        TypeVariable<?>[] typeVars = Map.class.getTypeParameters();

        assertEquals(2, result.size());
        assertEquals(String.class, result.get(typeVars[0]));
        assertEquals(Integer.class, result.get(typeVars[1]));
    }

    // --- Helper Fake Classes to simulate Reflection behavior ---

    private static class FakeParameterizedType implements ParameterizedType {
        private final Class<?> rawType;
        private final Type[] actualTypeArguments;

        FakeParameterizedType(Class<?> rawType, Type[] actualTypeArguments) {
            this.rawType = rawType;
            this.actualTypeArguments = actualTypeArguments;
        }

        @Override
        public Type getRawType() { return rawType; }

        @Override
        public Type[] getActualTypeArguments() { return actualTypeArguments; }

        @Override
        public Type getOwnerType() { return null; }
    }

    private static class FakeWildcardType implements WildcardType {
        private final Type bound;

        FakeWildcardType(Type bound) { this.bound = bound; }

        @Override
        public Type[] getUpperBounds() { return new Type[]{bound}; }

        @Override
        public Type[] getLowerBounds() { return new Type[0]; }
    }
}
